/**
 * The processor's P2P endpoint.
 */
public protocol P2pNodeProtocol: AnyObject, Sendable {
    
    /**
     * This processor's `EndpointId`, hex-encoded.
     */
    func endpointId()  -> String
    
    /**
     * Pings the hex-encoded `endpoint_id`, whose address comes from the registry.
     */
    func ping(endpointId: String) async throws  -> PingResult
    
    /**
     * Re-reads the relays listed on chain; returns whether they changed.
     */
    func refreshRelays() async throws  -> Bool
    
    /**
     * Whether this start registered the key on chain (first start, or a new key).
     */
    func registeredNow()  -> Bool
    
    /**
     * Whether the endpoint is connected to its home relay right now. Relay nodes notify new
     * assignments only while it is, so the app polls the chain more often while it is not.
     */
    func relayConnected()  -> Bool
    
    /**
     * URLs of the relays in use.
     */
    func relays()  -> [String]
    
    /**
     * Roles of the hex-encoded `endpoint_id`, as a bit set (1 registered, 2 processor, 4 manager,
     * 8 relay), cached like for incoming connections.
     */
    func roles(endpointId: String) async throws  -> UInt8
    
    /**
     * Starts accepting the assignment notices of relay nodes, passing each to `listener`; a
     * later call replaces the listener. (Async for the same reason as [`Self::serve_ping`].)
     */
    func serveAssignments(listener: AssignmentListener) async 
    
    /**
     * Starts accepting the commands of this processor's manager, passing them to `handler`; a
     * later call replaces the handler. (Async for the same reason as [`Self::serve_ping`].)
     */
    func serveManagerCommands(handler: ManagerCommandHandler) async 
    
    /**
     * Starts answering the pings of registered peers. (Async so that it runs on the library's
     * runtime, which accepting connections needs.)
     */
    func servePing() async 
    
    /**
     * Closes the endpoint and its connections. (Not `close`, which the Kotlin bindings use to
     * free the object.)
     */
    func shutdown() async 
    
    /**
     * Starts sending a network report (network type, home relay, direct and relayed connections)
     * every 30 minutes to the relay node of the home relay; a later call replaces the previous
     * one. (Async for the same reason as [`Self::serve_ping`].)
     */
    func startTelemetry(appVersion: String) async 
    
}
