/**
 * Outcome of [`P2pNode::ping`].
 */
public struct PingResult {
    /**
     * Milliseconds to set up the connection.
     */
    public var connectMs: UInt64
    /**
     * Milliseconds from sending `ping` to receiving `pong`.
     */
    public var rttMs: UInt64
    /**
     * Whether the connection went directly over IP rather than through a relay.
     */
    public var direct: Bool
    /**
     * The peer's address on a direct connection.
     */
    public var remoteAddr: String?
    /**
     * Whether the direct connection stays in the local network.
     */
    public var local: Bool

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(
        /**
         * Milliseconds to set up the connection.
         */connectMs: UInt64, 
        /**
         * Milliseconds from sending `ping` to receiving `pong`.
         */rttMs: UInt64, 
        /**
         * Whether the connection went directly over IP rather than through a relay.
         */direct: Bool, 
        /**
         * The peer's address on a direct connection.
         */remoteAddr: String?, 
        /**
         * Whether the direct connection stays in the local network.
         */local: Bool) {
        self.connectMs = connectMs
        self.rttMs = rttMs
        self.direct = direct
        self.remoteAddr = remoteAddr
        self.local = local
    }
}

#if compiler(>=6)
extension PingResult: Sendable {}
#endif


extension PingResult: Equatable, Hashable {
    public static func ==(lhs: PingResult, rhs: PingResult) -> Bool {
        if lhs.connectMs != rhs.connectMs {
            return false
        }
        if lhs.rttMs != rhs.rttMs {
            return false
        }
        if lhs.direct != rhs.direct {
            return false
        }
        if lhs.remoteAddr != rhs.remoteAddr {
            return false
        }
        if lhs.local != rhs.local {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(connectMs)
        hasher.combine(rttMs)
        hasher.combine(direct)
        hasher.combine(remoteAddr)
        hasher.combine(local)
    }
}



