        }
        if lhs.busy != rhs.busy {
            return false
        }
        if lhs.uptimeSecs != rhs.uptimeSecs {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(appVersion)
        hasher.combine(os)
        hasher.combine(batteryPercent)
        hasher.combine(charging)
        hasher.combine(busy)
        hasher.combine(uptimeSecs)
    }
